using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
namespace NoiteSemFim {
public static partial class SignatureArt {
 static Sprite arrow,slash;
 public static Sprite Arrow {get{if(arrow==null)arrow=Make(false);return arrow;}}
 public static Sprite Slash {get{if(slash==null)slash=Make(true);return slash;}}
 // Small native pixel shapes; the character artwork is generated separately.
 static Sprite Make(bool arc){const int n=96;var t=new Texture2D(n,n,TextureFormat.RGBA32,false){filterMode=FilterMode.Point};for(int y=0;y<n;y++)for(int x=0;x<n;x++){float dx=(x-47.5f)/46,dy=(y-47.5f)/46;float r=Mathf.Sqrt(dx*dx+dy*dy);bool on=arc?r>.77f&&r<.95f&&dx>.15f:Mathf.Abs(dy)<.025f&&dx>-.85f&&dx<.72f||dx>.44f&&dx<.88f&&Mathf.Abs(dy)<(.88f-dx)*.55f||dx<-.5f&&dx>-.82f&&Mathf.Abs(Mathf.Abs(dy)-(-dx-.5f)*.4f)<.035f;t.SetPixel(x,y,on?new Color(1,.95f,.8f,1):Color.clear);}t.Apply();return UnityEngine.Sprite.Create(t,new Rect(0,0,n,n),Vector2.one*.5f,n);}
}
public static partial class NewHeroSprites {
 static readonly Dictionary<int,Sprite[]> frames=new Dictionary<int,Sprite[]>();
 public static Sprite Get(int id,int frame){if(!frames.TryGetValue(id,out var sprites)){string name=id==3?"ren":id==4?"dante":"kaela";var t=Resources.Load<Texture2D>("Art/hero-"+name+"-v17");if(t==null)throw new InvalidOperationException("Missing new hero artwork: "+name);var px=t.GetPixels32();int w=t.width/3,h=t.height/2;sprites=new Sprite[6];var boxes=new RectInt[6];var roots=new float[6];var heights=new List<int>();for(int i=0;i<6;i++){int x0=(i%3)*w,y0=t.height-(i/3+1)*h,minX=x0+w,maxX=x0,minY=y0+h,maxY=y0;for(int y=y0;y<y0+h;y++)for(int x=x0;x<x0+w;x++)if(px[y*t.width+x].a>=150){minX=Mathf.Min(minX,x);maxX=Mathf.Max(maxX,x);minY=Mathf.Min(minY,y);maxY=Mathf.Max(maxY,y);}if(minX>=maxX)throw new InvalidOperationException("Empty hero pose "+name+" "+i);double sum=0,total=0;for(int y=minY+(maxY-minY)/3;y<minY+(maxY-minY)*2/3;y++)for(int x=minX;x<=maxX;x++)if(px[y*t.width+x].a>=200){sum+=x;total++;}roots[i]=total>0?(float)(sum/total):(minX+maxX)*.5f;boxes[i]=new RectInt(Mathf.Max(x0,minX-2),Mathf.Max(y0,minY-2),Mathf.Min(x0+w,maxX+3)-Mathf.Max(x0,minX-2),Mathf.Min(y0+h,maxY+3)-Mathf.Max(y0,minY-2));heights.Add(maxY-minY);}heights.Sort();float ppu=heights[3]/1.08f;for(int i=0;i<6;i++){var b=boxes[i];sprites[i]=UnityEngine.Sprite.Create(t,new Rect(b.x,b.y,b.width,b.height),new Vector2(Mathf.Clamp01((roots[i]-b.x)/b.width),2f/b.height),ppu,0,SpriteMeshType.FullRect);sprites[i].name="hero-"+name+"-v17_"+i;}frames[id]=sprites;}return sprites[Mathf.Clamp(frame,0,5)];}
}
public sealed partial class SurvivorGame {
 int StartingWeapon=>WeaponSlot(SelectedWeaponChoice,heroIndex);
 bool SignatureWeapon(int weapon)=>WeaponArchetype>=3&&weapon==(WeaponArchetype==5?0:1);
 float stationaryTime;
 sealed class SignatureVisual {public SpriteRenderer sprite;public Vector2 p;public float age,life,scale,angle;public Color color;public bool shadow;}
 readonly List<SignatureVisual> signatureVisuals=new List<SignatureVisual>();
 bool shadowPending;float shadowDelay;Vector2 shadowOrigin,shadowDirection;int shadowRank;float shadowPower,shadowArea;
 void ResetArchetype(){stationaryTime=0;shadowPending=false;shadowDelay=0;signatureVisuals.Clear();}
 string WeaponName(int id)=>!SignatureWeapon(id)?Catalog.Weapons[id]:WeaponArchetype==3?"Katana do Eclipse":WeaponArchetype==4?"Espadão das Cinzas":"Arco Lunar";
 string EvolvedWeaponName(int id)=>!SignatureWeapon(id)?Catalog.Evolved[id]:WeaponArchetype==3?"Mil Cortes do Eclipse":WeaponArchetype==4?"Ruína das Cinzas":"Chuva de Luas";
 string WeaponDescription(int id)=>!SignatureWeapon(id)?Catalog.WeaponText[id]:WeaponArchetype==3?"Cortes rápidos. 25% de chance de causar dano crítico duplo.":WeaponArchetype==4?"Golpe lento em cone amplo, atingindo todos os inimigos na área.":"Flechas atravessam inimigos. +60% de dano após ficar parada por 1 s.";
 void DrawHeroTabs(float x,float y,float width){float step=width/Catalog.Heroes.Length;for(int i=0;i<Catalog.Heroes.Length;i++)if(Button(Catalog.Heroes[i].Split(',')[0]+(IsHeroUnlocked(i)?"":" • X"),x+i*step,y,step-8,44,IsHeroUnlocked(i),heroIndex==i,14))heroIndex=i;}
 void UpdateArchetype(float dt,Vector2 movement){stationaryTime=movement.sqrMagnitude>.01f||dashTimer>0?0:Mathf.Min(2,stationaryTime+dt);for(int i=signatureVisuals.Count-1;i>=0;i--){var v=signatureVisuals[i];v.age+=dt;if(v.age>=v.life){if(v.sprite!=null)Dispose(v.sprite.gameObject);signatureVisuals.RemoveAt(i);continue;}v.sprite.color=new Color(v.color.r,v.color.g,v.color.b,(1-v.age/v.life)*v.color.a);}if(shadowPending){shadowDelay-=dt;if(shadowDelay<=0){shadowPending=false;MeleeStrike(shadowOrigin,shadowDirection,shadowRank,true,shadowPower,shadowArea);}}}
 void BeginNinjaShadow(){if(heroIndex!=3||WeaponArchetype!=3||PowerTarget(1)==null)return;shadowPending=true;shadowDelay=.32f;shadowOrigin=pos;shadowDirection=WeaponDirection(pos,Nearest());shadowRank=Mathf.Max(1,weapons[1]);shadowPower=Power;shadowArea=Area;AddSignatureVisual(DressedHero(5),pos,1.25f,new Color(.55f,.3f,1,.65f),.65f,0,true);}
 void AddSignatureVisual(Sprite art,Vector2 p,float size,Color c,float life,float angle,bool shadow=false){var r=Sprite(shadow?"Sombra do Eclipse":"Corte da arma",art,p,size,c,Depth(p)+3);r.transform.rotation=Quaternion.Euler(0,0,angle*Mathf.Rad2Deg);if(shadow)r.flipX=shadowDirection.x<0;signatureVisuals.Add(new SignatureVisual{sprite=r,p=p,scale=size,color=c,life=life,angle=angle,shadow=shadow});}
 bool ReleaseSignature(int weapon,int rank){if(!SignatureWeapon(weapon))return false;CastVisual();Vector2 aim=WeaponDirection(pos,Nearest());if(WeaponArchetype==5){int n=1+(evolved[weapon]?2:0);float damage=(15+rank*5)*Power*(stationaryTime>=1?1.6f:1)*(evolved[weapon]?1.8f:1);for(int i=0;i<n;i++){int before=shots.Count;Fire(pos,Rotate(aim,(i-(n-1)*.5f)*.12f)*13,damage,.16f*Area,3+rank/2,new Color(.8f,.95f,1),2.5f,0);if(shots.Count>before){var s=shots[shots.Count-1];s.lunarArrow=true;s.splitOnHit=HasAttackRelic;s.relicFxRow=HasAttackRelic?2:-1;s.sprite.sprite=HasAttackRelic?ArtBank.AttackRelicFx(2):SignatureArt.Arrow;s.sprite.transform.localScale=new Vector3(1.25f,.8f,1);}}}else {MeleeStrike(pos,aim,rank,false,Power,Area);if(state==ScreenState.Playing)ReleaseAttackRelic(aim,rank);}return true;}
 void MeleeStrike(Vector2 origin,Vector2 aim,int rank,bool echo,float power,float area){bool heavy=WeaponArchetype==4&&!echo;float radius=(heavy?2.65f:1.8f)*area+rank*.06f;float threshold=heavy?-.1f:.35f;float damage=(heavy?32+rank*9:11+rank*4)*power*(evolved[1]?1.8f:1);float angle=Mathf.Atan2(aim.y,aim.x);AddSignatureVisual(SignatureArt.Slash,origin+aim*radius*.38f,radius*1.7f,heavy?new Color(1,.5f,.2f):new Color(.76f,.6f,1),heavy?.32f:.18f,angle);var targets=enemies.ToArray();foreach(var e in targets){if(!enemies.Contains(e))continue;var d=e.p-origin;if(d.magnitude<=radius+(IsBoss(e.type)?.65f:.15f)&&(d.sqrMagnitude<.15f||Vector2.Dot(d.normalized,aim)>=threshold)){Damage(e,damage*(!heavy&&UnityEngine.Random.value<.25f?2:1));if(state!=ScreenState.Playing)break;}}}
 void SyncSignaturePixels(){foreach(var v in signatureVisuals){var p=Pixel(v.sprite,v.p,v.scale*(v.shadow?1.72f:1),v.shadow?.045f:.08f,!v.shadow,v.shadow,6);if(p!=null&&!v.shadow)p.view.transform.rotation=Quaternion.Euler(90,0,-v.angle*Mathf.Rad2Deg);}}
 string VerifyNewHeroes(){var account=save;int oldHero=heroIndex,oldDragon=selectedDragon,oldCurse=selectedCurse;bool previous=verifying,oldAim=manualAim;verifying=true;manualAim=true;save=new SaveData{rescuedHeroes=63,relicOwned=255};selectedDragon=selectedCurse=-1;
  var migrated=new SaveData{relicOwned=3,relicLoadouts=new[]{0,1,-1,-1,-1,-1}};migrated.NormalizeRelics();if(migrated.relicLoadouts.Length!=12||migrated.relicLoadouts[0]!=0||migrated.relicLoadouts[1]!=1||migrated.relicLoadouts[6]!=-1)throw new Exception("Six-hero save migration lost loadout");
  for(int h=3;h<6;h++){heroIndex=h;if(!IsHeroUnlocked(h))throw new Exception("New hero not playable");StartRun();if(weapons[StartingWeapon]!=1)throw new Exception("Incorrect new starting weapon");for(int frame=0;frame<6;frame++)if(ArtBank.Hero(h,frame)==null||!ArtBank.Hero(h,frame).name.Contains("v17"))throw new Exception("New hero frame missing");manualAimPoint=Vector2.right*6;lastAimDirection=Vector2.right;if(!TryEquipRelic(h,0)||!TryEquipRelic(h,1))throw new Exception("New hero relic cannot equip");StartRun();if(runArmor!=0||runTalisman!=1||EquippedRelic((h+1)%6,0)==0&&h==3)throw new Exception("New hero build isolation failed");}
  heroIndex=3;save.relicLoadouts[7]=-1;StartRun();manualAimPoint=Vector2.right*5;lastAimDirection=Vector2.right;var front=SpawnEnemy(0,false);front.p=Vector2.right;front.hp=front.maxHp=10000;var behind=SpawnEnemy(0,false);behind.p=Vector2.left;behind.hp=behind.maxHp=10000;UpdateWeapons(.01f);AdvanceWeaponsForCheck(.09f);if(front.hp<10000)throw new Exception("Katana skipped windup");AdvanceWeaponsForCheck(.03f);if(front.hp>=10000||behind.hp<10000||shots.Count!=0)throw new Exception("Katana cone failed");float before=front.hp;BeginNinjaShadow();UpdateArchetype(.30f,Vector2.zero);if(front.hp!=before)throw new Exception("Shadow strike fired too early");pos=Vector2.up*4;UpdateArchetype(.03f,Vector2.zero);if(front.hp>=before||behind.hp<10000)throw new Exception("Ninja echo origin/direction failed");StartRun();if(shadowPending||signatureVisuals.Count!=0)throw new Exception("Shadow leaked into new run");
  heroIndex=4;StartRun();manualAimPoint=Vector2.right*5;lastAimDirection=Vector2.right;var a=SpawnEnemy(0,false);a.p=new Vector2(1,1);a.hp=10000;var b=SpawnEnemy(0,false);b.p=new Vector2(1,-1);b.hp=10000;ReleasePower(1,1);if(a.hp>=10000||b.hp>=10000||WeaponPeriod(1)<1.5f||Speed>3)throw new Exception("Greatsword cleave or heavy pacing failed");
  heroIndex=5;StartRun();manualAimPoint=Vector2.right*5;lastAimDirection=Vector2.right;ReleasePower(0,1);float movingDamage=shots[0].damage;if(!shots[0].lunarArrow||shots[0].pierce<3)throw new Exception("Lunar arrow missing");UpdateArchetype(1.05f,Vector2.zero);ReleasePower(0,1);if(Mathf.Abs(shots[1].damage/movingDamage-1.6f)>.001f)throw new Exception("Stationary archer bonus missing");UpdateArchetype(.01f,Vector2.right);if(stationaryTime!=0)throw new Exception("Moving retained stationary bonus");var first=SpawnEnemy(0,false);first.p=new Vector2(.65f,0);first.hp=10000;var second=SpawnEnemy(0,false);second.p=new Vector2(1.3f,0);second.hp=10000;UpdateShots(.05f);UpdateShots(.05f);if(first.hp>=10000||second.hp>=10000)throw new Exception("Arrow did not pierce aligned enemies");
  foreach(int h in new[]{3,4,5}){heroIndex=h;StartFinal3DDemo();AdvanceFinalTransition(4);AnimateHero(.15f,Vector2.right);FinalCamera();SyncPixelFinal();if(!final3DActive||cam.orthographic||!pixelFinal.TryGetValue(hero,out var pixel)||pixel.view.sprite!=hero.sprite)throw new Exception("New hero absent from 2.5D final");}
  save=account;heroIndex=oldHero;selectedDragon=oldDragon;selectedCurse=oldCurse;manualAim=oldAim;verifying=previous;ReturnMenu();return "New heroes PASS: 18 pixel animation poses, six-hero save migration/equipment isolation, delayed katana cone, dodge echo at original position, heavy multi-target cleave, piercing lunar arrows, stationary/moving damage, reset and 2.5D final rendering.";
 }
 IEnumerator CaptureNewHeroes(string folder){verifying=true;Application.runInBackground=true;System.IO.Directory.CreateDirectory(folder);var account=save;save=new SaveData{totalKills=1000,wins=1,dragonUnlocks=7};selectedDragon=selectedCurse=-1;manualAim=true;heroIndex=3;OpenSelection();yield return Capture(folder,"seis-herois-v17");foreach(int h in new[]{3,4,5}){heroIndex=h;StartRun();elementPreviewFrozen=true;manualAimPoint=Vector2.right*6;lastAimDirection=Vector2.right;for(int i=0;i<5;i++){var e=SpawnEnemy(0,false);e.p=new Vector2(1.3f+i*.4f,(i%3-1)*.55f);e.hp=10000;e.sprite.transform.position=e.p;}if(h==3)BeginNinjaShadow();if(h==5)stationaryTime=1.2f;ReleasePower(StartingWeapon,3);AnimateHero(.01f,Vector2.zero);hero.flipX=false;UpdateShots(.02f);yield return Capture(folder,"heroi-"+h+"-combate-v17");elementPreviewFrozen=false;StartFinal3DDemo();elementPreviewFrozen=true;AdvanceFinalTransition(4);FinalCamera();AnimateHero(.15f,Vector2.right);SyncPixelFinal();yield return Capture(folder,"heroi-"+h+"-arena-v17");elementPreviewFrozen=false;ReturnMenu();}save=account;Debug.Log("NEW HERO CAPTURE PASS");Application.Quit();}
}
}
